def ovs_mapping(*, mappings: tuple[str, ...]) -> Footprint:
    """OVSMapping (learned with markers only)."""
    added: dict[str, Any] = {}
    changed: dict[str, Any] = {}
    removed: list[str] = []
    for element in mappings:
        match = re.fullmatch("(?P<network>.+?):(?P<bridge>.+?)", element)
        if match is None:
            raise NotLearned(f"OVSMapping.mappings: {element!r} is no '{{network}}:{{bridge}}'")
        (
            network,
            bridge,
        ) = (
            match.group("network"),
            match.group("bridge"),
        )
        added.update({})
        changed.update(
            {
                f"ovs.bridge:{bridge}": {
                    "externalIds": {"from": {}, "to": {"ovn-bridge-mappings": network}}
                }
            }
        )
        removed.extend([])
    return {"added": added, "changed": changed, "removed": removed}


